	@Test
	void deeplyNestedTermsHaveLinearEstimatesAndTraversal(@TempDir File directory) throws Exception {
		AtomicInteger accesses = new AtomicInteger();
		Value value = VF.createLiteral("leaf");
		int depth = 16384;
		for (int i = 0; i < depth; i++) {
			value = new Term(value, accesses);
		}
		Statement statement = statement(value);
		try (TestValueStore store = new TestValueStore(directory, new LmdbStoreConfig())) {
			long bytes = assertDoesNotThrow(() -> store.estimateWriteBytes(List.of(statement)));
			assertTrue(bytes > 0L && bytes < depth * 4096L, "dictionary overhead must scale linearly with nesting");
			assertTrue(accesses.get() < depth * 8L, "estimating must not recursively hash every suffix");
			accesses.set(0);
			long batchBytes = assertDoesNotThrow(() -> store.estimateWriteBytes(List.of(statement, statement)));
			assertTrue(batchBytes > 0L && batchBytes < depth * 4096L,
					"the distinct-count path must also scale linearly with nesting");
			assertTrue(accesses.get() < depth * 16L);
		}
		accesses.set(0);
		long retained = assertDoesNotThrow(() -> ValueStore.estimatedRetainedBytes(statement));
		assertTrue(retained > 0L && retained < depth * 1024L);
		assertTrue(accesses.get() < depth * 8L);
	}

	@Test
	void cyclesAreRejectedWithoutRecursiveHashing(@TempDir File directory) throws Exception {
		Term self = new Term(null, new AtomicInteger());
		self.object = self;
		Term first = new Term(null, new AtomicInteger());
		Term second = new Term(first, new AtomicInteger());
		first.object = second;
		Value prefixed = first;
		for (int i = 0; i < 127; i++) {
			prefixed = new Term(prefixed, new AtomicInteger());
		}
		try (TestValueStore store = new TestValueStore(directory, new LmdbStoreConfig())) {
			for (Value term : List.of(self, first, prefixed)) {
				Statement statement = statement(term);
				assertThrows(IllegalArgumentException.class, () -> store.estimateWriteBytes(List.of(statement)));
				assertThrows(IllegalArgumentException.class,
						() -> store.estimateWriteBytes(List.of(statement, statement)));
				assertThrows(IllegalArgumentException.class, () -> ValueStore.estimatedRetainedBytes(statement));
			}
		}
	}

	@Test
	void repeatedLargeValuesDoNotMultiplyMapDemand(@TempDir File directory) throws Exception {
		Value large = VF.createLiteral("語".repeat(1024 * 1024));
		List<Statement> repeated = new ArrayList<>();
		for (int i = 0; i < 1024; i++) {
			repeated.add(VF.createStatement(VF.createIRI("urn:estimate:" + i), PREDICATE, large));
		}
		try (TestValueStore store = new TestValueStore(directory, new LmdbStoreConfig())) {
			long single = store.estimateWriteBytes(List.of(repeated.get(0)));
			long batch = store.estimateWriteBytes(repeated);
			assertTrue(batch >= single);
			assertTrue(batch < single * 2L, "repeated payloads must not request one map-sized copy per occurrence");
			store.growMapForEstimatedWrite(batch, null);
			assertTrue(store.mapSizeBytes() < single * 8L,
					"growth must not reserve one native copy per occurrence of the repeated payload");
		}
	}

	@Test
	void largeOutlierIsNotAveragedAwayAndJavaHashCollisionsStayDistinct(@TempDir File directory) throws Exception {
		List<Statement> statements = new ArrayList<>();
		long payloadBytes = 0L;
		for (int i = 0; i < 1024; i++) {
			StringBuilder label = new StringBuilder();
			for (int bit = 0; bit < 10; bit++) {
				label.append((i & (1 << bit)) == 0 ? "Aa" : "BB");
			}
			statements.add(statement(VF.createLiteral(label.toString())));
			payloadBytes += label.toString().getBytes(StandardCharsets.UTF_8).length * 4L + 256L;
		}
		String outlier = "雪".repeat(1024 * 1024);
		statements.add(statement(VF.createLiteral(outlier)));
		payloadBytes += outlier.getBytes(StandardCharsets.UTF_8).length * 4L + 256L;
		for (int i = 0; i < 4096; i++) {
			statements.add(statements.get(0));
		}
		try (TestValueStore store = new TestValueStore(directory, new LmdbStoreConfig())) {
			assertTrue(store.estimateWriteBytes(statements) >= payloadBytes,
					"distinct-byte estimates must preserve hash-colliding lexical values and rare large values");
		}
	}

