	@Test
	void equalSharedNestedTermsAreCountedByStructure(@TempDir File directory) throws Exception {
		Value leaf = VF.createLiteral("shared".repeat(8192));
		Value first = leaf;
		Value equal = VF.createLiteral(leaf.stringValue());
		for (int i = 0; i < 32; i++) {
			first = VF.createTripleTerm(SUBJECT, PREDICATE, first);
			equal = VF.createTripleTerm(SUBJECT, PREDICATE, equal);
		}
		try (TestValueStore store = new TestValueStore(directory, new LmdbStoreConfig())) {
			long single = store.estimateWriteBytes(List.of(statement(first)));
			long shared = store.estimateWriteBytes(List.of(statement(first), statement(first), statement(equal)));
			assertTrue(single < 2L * 1024L * 1024L, "nested estimates must not multiply the leaf by every ancestor");
			assertTrue(shared <= single * 2L, "equal nested terms must share a cardinality estimate");
			assertEquals(store.estimateWriteBytes(List.of(statement(first), statement(first))),
					store.estimateWriteBytes(List.of(statement(first), statement(equal))),
					"equal structural values must produce the same estimate regardless of object identity");
		}
	}

