	@Test
	void consecutiveChainsObserveEveryChangedComponent() {
		Value leaf = VF.createLiteral("leaf");
		Value typed = VF.createLiteral("leaf", VF.createIRI("urn:estimate:type"));
		Value english = VF.createLiteral("leaf", "en");
		Value german = VF.createLiteral("leaf", "de");
		Resource otherSubject = VF.createIRI("urn:estimate:other-subject");
		Resource bnode = VF.createBNode(SUBJECT.stringValue());
		DictionaryByteEstimate estimate = new DictionaryByteEstimate(true);
		for (Value scalar : List.of(SUBJECT, PREDICATE, leaf, typed, english, german, otherSubject, bnode)) {
			estimate.add(scalar);
		}
		estimate.add(chain(leaf, 3, SUBJECT));
		long base = estimate.bytes();
		estimate.add(chain(VF.createLiteral("leaf"), 3, SUBJECT));
		assertEquals(base, estimate.bytes());
		for (Value changed : List.of(chain(leaf, 3, otherSubject), chain(leaf, 3, bnode),
				chain(typed, 3, SUBJECT), chain(english, 3, SUBJECT), chain(german, 3, SUBJECT))) {
			long before = estimate.bytes();
			estimate.add(changed);
			assertTrue(estimate.bytes() > before, "new subterms must be recorded even when scalars were already seen");
		}
		long beforeShorter = estimate.bytes();
		estimate.add(chain(leaf, 2, SUBJECT));
		assertEquals(beforeShorter, estimate.bytes(), "a shorter existing suffix introduces no new records");
		estimate.add(chain(leaf, 4, SUBJECT));
		assertTrue(estimate.bytes() > beforeShorter, "a longer chain introduces a new outer record");
	}

	private static Value chain(Value leaf, int depth, Resource middleSubject) {
		Value value = leaf;
		for (int i = 0; i < depth; i++) {
			value = VF.createTripleTerm(i == 1 ? middleSubject : SUBJECT, PREDICATE, value);
		}
		return value;
	}

