	@Test
	void mutableValuesDoNotReuseStaleLexicalHashes(@TempDir File directory) throws Exception {
		try (TestValueStore store = new TestValueStore(directory, new LmdbStoreConfig())) {
			DictionaryByteEstimate estimate = new DictionaryByteEstimate(true);
			LmdbLiteral literal = store.createLiteral("雪".repeat(16384));
			estimate.add(literal);
			literal.setLabel("語".repeat(16384));
			estimate.add(literal);
			assertTrue(estimate.bytes() >= 2L * 16384L * 3L * 4L,
					"hash memoization must follow immutable lexical strings rather than mutable model identities");

			DictionaryByteEstimate iris = new DictionaryByteEstimate(true);
			LmdbIRI iri = store.createIRI("urn:" + "雪".repeat(16384));
			iris.add(iri);
			iri.setNamespaceAndIri("urn:", "語".repeat(16384));
			iris.add(iri);
			assertTrue(iris.bytes() >= 2L * 16384L * 3L * 4L);

			DictionaryByteEstimate bnodes = new DictionaryByteEstimate(true);
			LmdbBNode bnode = store.createBNode("雪".repeat(16384));
			bnodes.add(bnode);
			bnode.setID("語".repeat(16384));
			bnodes.add(bnode);
			assertTrue(bnodes.bytes() >= 2L * 16384L * 3L * 4L);

			DictionaryByteEstimate nested = new DictionaryByteEstimate(true);
			Value term = VF.createTripleTerm(SUBJECT, PREDICATE, literal);
			nested.add(term);
			literal.setLabel("葉".repeat(16384));
			nested.add(term);
			assertTrue(nested.bytes() >= 2L * 16384L * 3L * 4L,
					"a shared term must observe mutations in its descendants");
		}
	}

