	@Test
	void nestedTermsAndRepeatedPayloadsCommitThroughNativeGrowth(@TempDir File directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setValueDBSize(256 * 1024L).setTripleDBSize(256 * 1024L);
		SailRepository repository = new SailRepository(new LmdbStore(directory, config));
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			Value value = VF.createLiteral("雪".repeat(64 * 1024));
			for (int i = 0; i < 32; i++) {
				value = VF.createTripleTerm(SUBJECT, PREDICATE, value);
			}
			connection.begin(IsolationLevels.READ_COMMITTED);
			for (int i = 0; i < 16; i++) {
				connection.add(VF.createIRI("urn:estimate:write:" + i), PREDICATE, value);
			}
			connection.commit();
			assertTrue(connection.size() == 16L);
			assertTrue(connection.hasStatement(VF.createIRI("urn:estimate:write:0"), PREDICATE, value, false));
		} finally {
			repository.shutDown();
		}
	}

	private static Statement statement(Value value) {
		return VF.createStatement(SUBJECT, PREDICATE, value);
	}

	private static final class TestValueStore extends ValueStore implements AutoCloseable {
		private TestValueStore(File directory, LmdbStoreConfig config) throws IOException {
			super(directory, config);
		}
	}

	private static final class Term extends AbstractTripleTerm {
		private Value object;
		private final AtomicInteger accesses;

		private Term(Value object, AtomicInteger accesses) {
			this.object = object;
			this.accesses = accesses;
		}

		@Override
		public Resource getSubject() {
			return SUBJECT;
		}

		@Override
		public IRI getPredicate() {
			return PREDICATE;
		}

		@Override
		public Value getObject() {
			accesses.incrementAndGet();
			return object;
		}
	}
